import sys
from collections import deque

def main():
    input = sys.stdin.read
    data = input().split()
    H = int(data[0])
    W = int(data[1])
    S = data[2:2+H]

    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    is_empty = [[False]*W for _ in range(H)]
    is_free = [[False]*W for _ in range(H)]

    for i in range(H):
        for j in range(W):
            if S[i][j] == '.':
                is_empty[i][j] = True

    for i in range(H):
        for j in range(W):
            if not is_empty[i][j]:
                continue
            has_magnet = False
            for di,dj in directions:
                ni,nj = i+di, j+dj
                if 0<=ni<H and 0<=nj<W and S[ni][nj]=='#':
                    has_magnet = True
                    break
            if not has_magnet:
                is_free[i][j] = True

    visited = [[False]*W for _ in range(H)]
    max_deg = 1

    for i in range(H):
        for j in range(W):
            if is_free[i][j] and not visited[i][j]:
                # BFS for component
                component = []
                q = deque()
                q.append((i,j))
                visited[i][j] = True
                while q:
                    x,y = q.popleft()
                    component.append((x,y))
                    for dx,dy in directions:
                        nx,ny = x+dx, y+dy
                        if 0<=nx<H and 0<=ny<W and is_free[nx][ny] and not visited[nx][ny]:
                            visited[nx][ny] = True
                            q.append((nx,ny))

                # Now find adjacent non-free empties
                adj_nonfree = set()
                for x,y in component:
                    for dx,dy in directions:
                        nx,ny = x+dx, y+dy
                        if 0<=nx<H and 0<=ny<W and is_empty[nx][ny] and not is_free[nx][ny]:
                            adj_nonfree.add((nx,ny))

                deg = len(component) + len(adj_nonfree)
                if deg > max_deg:
                    max_deg = deg

    print(max_deg)

main()
