def lastSubstringBeforeEmpty(s):
    from collections import Counter
    freq = Counter(s)
    if not freq:
        return ""
    maxf = max(freq.values())
    last_pos = {}
    for i, c in enumerate(s):
        if freq[c] == maxf:
            last_pos[c] = i
    positions = sorted(last_pos.values())
    return ''.join(s[p] for p in positions)
