import sys

def solve():
    input_lines = [sys.stdin.readline().strip() for _ in range(12)]
    pieces = []
    for p in range(3):
        cells = []
        for i in range(4):
            line = input_lines[p*4 + i]
            for j in range(4):
                if line[j] == '#':
                    cells.append((i, j))
        pieces.append(cells)

    def get_all_placements(cells):
        placements = set()
        for rot in range(4):
            if rot == 0:
                rotated = cells[:]
            else:
                rotated = [(c, -r) for r, c in rotated]
                min_r = min(r for r, c in rotated)
                min_c = min(c for r, c in rotated)
                rotated = [(r - min_r, c - min_c) for r, c in rotated]
            max_r = max(r for r, c in rotated)
            max_c = max(c for r, c in rotated)
            for sr in range(4 - max_r):
                for sc in range(4 - max_c):
                    mask = 0
                    valid = True
                    for r, c in rotated:
                        nr, nc = r + sr, c + sc
                        if 0 <= nr < 4 and 0 <= nc < 4:
                            mask |= (1 << (nr * 4 + nc))
                        else:
                            valid = False
                            break
                    if valid:
                        placements.add(mask)
        return list(placements)

    all_placements = [get_all_placements(piece) for piece in pieces]

    total = (1 << 16) - 1
    for m1 in all_placements[0]:
        for m2 in all_placements[1]:
            if m1 & m2 != 0:
                continue
            for m3 in all_placements[2]:
                if m1 & m3 != 0 or m2 & m3 != 0:
                    continue
                if (m1 | m2 | m3) == total:
                    print("Yes")
                    return
    print("No")

solve()
