import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    M = int(data[1])
    wmat = [[float('inf')] * N for _ in range(N)]
    index = 2
    for _ in range(M):
        U = int(data[index]) - 1
        V = int(data[index + 1]) - 1
        W = int(data[index + 2])
        wmat[U][V] = W
        index += 3
    INF = float('inf')
    dp = [[INF] * N for _ in range(1 << N)]
    for i in range(N):
        dp[1 << i][i] = 0
    for mask in range(1 << N):
        for _ in range(N):
            updated = False
            for u in range(N):
                if dp[mask][u] >= INF:
                    continue
                for v in range(N):
                    if wmat[u][v] >= INF:
                        continue
                    nmask = mask | (1 << v)
                    newcost = dp[mask][u] + wmat[u][v]
                    if newcost < dp[nmask][v]:
                        dp[nmask][v] = newcost
                        updated = True
            if not updated:
                break
    full = (1 << N) - 1
    ans = min(dp[full])
    if ans >= INF:
        print("No")
    else:
        print(ans)

solve()
