def countBeautifulNumbers(low: int, high: int, k: int) -> int:
    def count_up_to(n: int) -> int:
        if n < 0:
            return 0
        s = str(n)
        L = len(s)
        from functools import lru_cache
        @lru_cache(None)
        def dp(pos: int, tight: int, lead: int, even_c: int, odd_c: int, mod: int) -> int:
            if pos == L:
                return 1 if lead == 0 and even_c == odd_c and mod == 0 else 0
            res = 0
            up = int(s[pos]) if tight else 9
            for d in range(up + 1):
                new_tight = 1 if tight and d == up else 0
                if lead and d == 0:
                    res += dp(pos + 1, new_tight, 1, even_c, odd_c, mod)
                else:
                    new_even = even_c + (1 if d % 2 == 0 else 0)
                    new_odd = odd_c + (1 if d % 2 == 1 else 0)
                    new_mod = (mod * 10 + d) % k
                    res += dp(pos + 1, new_tight, 0, new_even, new_odd, new_mod)
            return res
        return dp(0, 1, 1, 0, 0, 0)
    return count_up_to(high) - count_up_to(low - 1)
```

