def minPartitions(s: str) -> int:
    n = len(s)
    prefix = [[0] * (n + 1) for _ in range(26)]
    for i in range(n):
        for c in range(26):
            prefix[c][i + 1] = prefix[c][i]
        prefix[ord(s[i]) - ord('a')][i + 1] += 1
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(i):
            freqs = []
            for c in range(26):
                f = prefix[c][i] - prefix[c][j]
                if f > 0:
                    freqs.append(f)
            if freqs and all(f == freqs[0] for f in freqs):
                dp[i] = min(dp[i], dp[j] + 1)
    return dp[n]
