def longestSpecialSubstring(s):
    n = len(s)
    ans = -1
    for ch in set(s):
        runs = []
        i = 0
        while i < n:
            if s[i] == ch:
                j = i
                while j < n and s[j] == ch:
                    j += 1
                runs.append(j - i)
                i = j
            else:
                i += 1
        for length in range(1, n + 1):
            occ = 0
            for r in runs:
                if r >= length:
                    occ += r - length + 1
            if occ >= 3:
                ans = max(ans, length)
    return ans
