def check_line(color, board):
    # board: 0 white, 1 red, 2 blue
    for i in range(3):
        if all(board[i][j] == color for j in range(3)):
            return True
        if all(board[j][i] == color for j in range(3)):
            return True
    if all(board[i][i] == color for i in range(3)):
        return True
    if all(board[i][2-i] == color for i in range(3)):
        return True
    return False

def game_over(board):
    return all(board[i][j] != 0 for i in range(3) for j in range(3))

def get_score(A, board, color):
    s = 0
    for i in range(3):
        for j in range(3):
            if board[i][j] == color:
                s += A[i][j]
    return s

def solve(A):
    # 0: white, 1: red (Takahashi), 2: blue (Aoki)
    # We need to determine winner with optimal play
    # Use recursion with memoization on state
    # State can be represented as tuple of tuples for board, and whose turn

    from functools import lru_cache

    init_board = tuple(tuple(0 for _ in range(3)) for _ in range(3))

    @lru_cache(maxsize=None)
    def dfs(board, turn):
        # turn: 1 Takahashi, 2 Aoki
        # Returns True if the starting player of this turn wins? No, we need absolute: True if Takahashi wins
        # Actually, since we want who wins, return 'Takahashi' or 'Aoki' the overall winner

        # Find possible moves
        moves = [(i,j) for i in range(3) for j in range(3) if board[i][j] == 0]
        if not moves:
            # Should not reach here as game ends when full after move
            pass

        for mi, mj in moves:
            new_board_list = [list(row) for row in board]
            new_board_list[mi][mj] = turn
            new_board = tuple(tuple(row) for row in new_board_list)

            # Check if this player formed a line
            if check_line(turn, new_board):
                if turn == 1:
                    return 'Takahashi'
                else:
                    return 'Aoki'

            if game_over(new_board):
                # Compare scores
                score_t = get_score(A, new_board, 1)
                score_a = get_score(A, new_board, 2)
                if score_t > score_a:
                    return 'Takahashi'
                else:
                    return 'Aoki'

            # Continue to next player
            next_turn = 3 - turn
            result = dfs(new_board, next_turn)
            if result == 'Takahashi':
                # If Takahashi wins from here, and if it's his goal
                # Since both play optimally to win themselves
                # We need to choose the move that benefits the current player
                # So we have to collect if current can force his win
                # Thus, better to return whether current player can force win or not? Let's adjust.
                pass  # This approach is wrong, need to redo logic.

        # Redefine dfs to return the winner assuming optimal
        # But to handle optimal, each player chooses move that makes him win if possible
        # So let's make dfs return the winner
        # For current turn player, he tries moves, if any move leads to his win, he chooses it
        # Else, the opponent wins.

    # Redefine properly
    @lru_cache(maxsize=None)
    def dfs_winner(board, turn):
        moves = [(i,j) for i in range(3) for j in range(3) if board[i][j] == 0]
        my_win = 'Takahashi' if turn == 1 else 'Aoki'
        opp_win = 'Aoki' if turn == 1 else 'Takahashi'

        can_force_win = False
        for mi, mj in moves:
            new_board_list = [list(row) for row in board]
            new_board_list[mi][mj] = turn
            new_board = tuple(tuple(row) for row in new_board_list)

            if check_line(turn, new_board):
                return my_win  # I win immediately
            if game_over(new_board):
                score_t = get_score(A, new_board, 1)
                score_a = get_score(A, new_board, 2)
                winner = 'Takahashi' if score_t > score_a else 'Aoki'
                if winner == my_win:
                    return my_win
                else:
                    continue  # this move loses, try others
            # recurse
            res = dfs_winner(new_board, 3 - turn)
            if res == my_win:
                return my_win  # I can force win by this move
        # If no move allows me to win, then opponent wins
        return opp_win

    return dfs_winner(init_board, 1)

def main():
    A = read_input()
    winner = solve(A)
    print(winner)

if __name__ == "__main__":
    main()
