def minChanges(s: str, k: int) -> int:
    n = len(s)
    INF = 10**9
    cost = [[INF] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 2, n + 1):
            m = j - i
            min_c = INF
            for d in range(1, m):
                if m % d != 0:
                    continue
                c = 0
                p = m // d
                for r in range(d):
                    seq = [s[i + r + t * d] for t in range(p)]
                    for t in range(p // 2):
                        if seq[t] != seq[p - 1 - t]:
                            c += 1
                min_c = min(min_c, c)
            cost[i][j - 1] = min_c
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(1, min(k, i // 2) + 1):
            for prev in range(2 * (j - 1), i - 1):
                if dp[prev][j - 1] != INF and cost[prev][i - 1] != INF:
                    dp[i][j] = min(dp[i][j], dp[prev][j - 1] + cost[prev][i - 1])
    return dp[n][k]
