class TrieNode:
    def __init__(self):
        self.children = [None] * 26
        self.best_idx = -1
        self.best_len = float('inf')

def answerQueries(wordsContainer, wordsQuery):
    root = TrieNode()
    n = len(wordsContainer)
    for i in range(n):
        word = wordsContainer[i]
        length = len(word)
        node = root
        if length < node.best_len or (length == node.best_len and i < node.best_idx):
            node.best_idx = i
            node.best_len = length
        for char in reversed(word):
            idx = ord(char) - ord('a')
            if node.children[idx] is None:
                node.children[idx] = TrieNode()
            node = node.children[idx]
            if length < node.best_len or (length == node.best_len and i < node.best_idx):
                node.best_idx = i
                node.best_len = length
    ans = []
    for query in wordsQuery:
        node = root
        for char in reversed(query):
            idx = ord(char) - ord('a')
            if node.children[idx] is None:
                break
            node = node.children[idx]
        ans.append(node.best_idx)
    return ans
