def minimize_value(s):
    from collections import Counter
    import heapq
    n = len(s)
    g = [0] * 26
    q = 0
    for c in s:
        if c == '?':
            q += 1
        else:
            g[ord(c) - ord('a')] += 1
    f = g[:]
    pq = []
    for i in range(26):
        heapq.heappush(pq, (f[i], i))
    for _ in range(q):
        val, idx = heapq.heappop(pq)
        f[idx] += 1
        heapq.heappush(pq, (val + 1, idx))
    quota = [f[i] - g[i] for i in range(26)]
    res = list(s)
    for i in range(n):
        if res[i] == '?':
            for j in range(26):
                if quota[j] > 0:
                    res[i] = chr(ord('a') + j)
                    quota[j] -= 1
                    break
    return ''.join(res)
