def waysToReachStair(k: int) -> int:
    import functools

    def count_ways(m: int, d: int) -> int:
        if d < 0 or d > m + 1:
            return 0
        @functools.lru_cache(None)
        def dp(u: int, dd: int, last_d: int) -> int:
            if u == m and dd == d:
                return 1
            res = 0
            # do up
            if u < m:
                res += dp(u + 1, dd, 0)
            # do down
            if dd < d and last_d == 0:
                pos = (1 << u) - dd
                if pos > 0:
                    res += dp(u, dd + 1, 1)
            return res
        # initial: u=0, dd=0, last_d=0, pos=1
        return dp(0, 0, 0)

    ans = 0
    for m in range(62):
        d = (1 << m) - k
        ans += count_ways(m, d)
    return ans
