                if mask & (1 << i):
                    # Calculate LCM of selected coins
                    import math
                    lcm_val = lcm_val * coins[i] // math.gcd(lcm_val, coins[i])
                    # Check for overflow
                    if lcm_val > max_val:
                        valid = False
                        break
                    bit_count += 1

            if valid:
                if bit_count % 2 == 1:
                    count += max_val // lcm_val
                else:
                    count -= max_val // lcm_val

        return count

    # Binary search on the answer
    left, right = 1, k * min(coins)

    while left < right:
        mid = (left + right) // 2
        if count_total_multiples(mid) < k:
            left = mid + 1
        else:
            right = mid

    return left
