                    dp[i + 1][j][0] = max(dp[i + 1][j][0], dp[i][j][0])
                else:
                    dp[i + 1][j][0] = max(dp[i + 1][j][0], dp[i][j][1])
                # take nums[i]
                if s == 0:
                    # start new segment if j < k
                    if j < k:
                        nj = j + 1
                        dp[i + 1][nj][1] = max(dp[i + 1][nj][1], dp[i][j][0] + c[nj] * nums[i])
