def maxLength(x: int, y: int, z: int) -> int:
    from functools import lru_cache
    @lru_cache(None)
    def dp(a, b, c, last, streak):
        if a < 0 or b < 0 or c < 0:
            return 0
        res = 0
        # try add AA
        if a > 0:
            if last == 'A':
                if streak < 2:
                    res = max(res, 2 + dp(a-1, b, c, 'A', streak+1))
            else:
                res = max(res, 2 + dp(a-1, b, c, 'A', 1))
        # try add BB
        if b > 0:
            if last == 'B':
                if streak < 2:
                    res = max(res, 2 + dp(a, b-1, c, 'B', streak+1))
            else:
                res = max(res, 2 + dp(a, b-1, c, 'B', 1))
        # try add AB
        if c > 0:
            if last == 'A':
                if streak < 2:
                    res = max(res, 2 + dp(a, b, c-1, 'B', 1))
            else:
                res = max(res, 2 + dp(a, b, c-1, 'B', 1))
        return res
    return dp(x, y, z, '', 0)
