def longestCommonPrefix(arr1, arr2):
    class TrieNode:
        def __init__(self):
            self.children = {}
    def insert(root, num):
        node = root
        for digit in str(num):
            if digit not in node.children:
                node.children[digit] = TrieNode()
            node = node.children[digit]
    def query(root, num):
        node = root
        length = 0
        for digit in str(num):
            if digit in node.children:
                node = node.children[digit]
                length += 1
            else:
                break
        return length
    root = TrieNode()
    for num in arr1:
        insert(root, num)
    max_len = 0
    for num in arr2:
        max_len = max(max_len, query(root, num))
    return max_len
