import sys
import math
from collections import Counter

def smallest_prime_factor(n):
    spf = [i for i in range(n+1)]
    for i in range(2, int(math.sqrt(n))+1):
        if spf[i] == i:
            for j in range(i*i, n+1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

def get_square_free(x, spf):
    if x == 0:
        return 0
    res = 1
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        if cnt % 2 == 1:
            res *= p
    return res

def main():
