    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:1+N]))
    MAX_A = 200000
    spf = smallest_prime_factor(MAX_A)
    zero_count = 0
    non_zero_kernels = []
    for a in A:
        if a == 0:
            zero_count += 1
        else:
            k = get_square_free(a, spf)
            non_zero_kernels.append(k)
    total = 0
    # Pairs with zeros
    total += zero_count * (N - zero_count) + (zero_count * (zero_count - 1)) // 2
    # Pairs among non-zeros
    freq = Counter(non_zero_kernels)
    for f in freq.values():
        total += (f * (f - 1)) // 2
    print(total)

