def findMaximumNum(k: int, x: int) -> int:
    def count_bit_set_up_to(n, b):
        if n < 0:
            return 0
        p = 1 << b
        full = (n + 1) // (p * 2) * p
        rem = max(0, (n + 1) % (p * 2) - p)
        return full + rem

    def total_price(num, x):
        if num <= 0:
            return 0
        total = 0
        pos = x
        while True:
            b = pos - 1
            if (1 << b) > num:
                break
            total += count_bit_set_up_to(num, b)
            pos += x
            if pos > 60:
                break
        return total

    low = 0
    high = 10**18
    while low < high:
        mid = (low + high + 1) // 2
        if total_price(mid, x) <= k:
            low = mid
        else:
            high = mid - 1
    return low
