    ans = 0
    # descendants
    if K < 60:
        left = X << K
        if left <= N:
            right = left + (1 << K) - 1
            ans += min(N, right) - left + 1
    # going up
    cur = X
    for u in range(1, min(K, 60) + 1):
        if cur == 1:
            break
        parent = cur // 2
        rem = K - u
        if rem == 0:
            ans += 1
        else:
            other = parent * 2 if parent * 2 != cur else parent * 2 + 1
            if other <= N:
                d = rem - 1
                if d < 60:
                    lft = other << d
                    if lft <= N:
                        rgt = lft + (1 << d) - 1
                        ans += min(N, rgt) - lft + 1
        cur = parent
    return ans

def main():
    input = sys.stdin.read
    data = input().split()
    T = int(data[0])
    index = 1
    for _ in range(T):
        N = int(data[index])
        X = int(data[index + 1])
        K = int(data[index + 2])
        index += 3
        print(count_at_dist(N, X, K))

if __name__ == "__main__":
