def minCost(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    n = len(source)
    INF = math.inf
    dist = [[INF] * 26 for _ in range(26)]
    for i in range(26):
        dist[i][i] = 0
    for o, c, z in zip(original, changed, cost):
        u = ord(o) - ord('a')
        v = ord(c) - ord('a')
        dist[u][v] = min(dist[u][v], z)
    for k in range(26):
        for i in range(26):
            for j in range(26):
                if dist[i][k] < INF and dist[k][j] < INF:
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])
    total = 0
