def countPowerfulNumbers(start: int, finish: int, limit: int, s: str) -> int:
    def count(n: int) -> int:
        if n <= 0:
            return 0
        S = str(n)
        N = len(S)
        L = len(s)
        if N < L:
            return 0
        res = 0
        if int(s) <= n:
            res += 1
        for leng in range(L + 1, N):
            pre = leng - L
            res += limit * ((limit + 1) ** (pre - 1))
        # length == N
        def dfs(pos: int, tight: bool, leading_zero: bool) -> int:
            if pos == N:
                return 0 if leading_zero else 1
            if pos >= N - L and not leading_zero:
                # must match suffix
                digit = int(s[pos - (N - L)])
                if tight and digit > int(S[pos]):
                    return 0
                new_tight = tight and (digit == int(S[pos]))
                if digit > limit:
                    return 0
                return dfs(pos + 1, new_tight, False)
            key = (pos, tight, leading_zero)
            if key in memo:
                return memo[key]
            up = int(S[pos]) if tight else limit
            ans = 0
            start_d = 0 if not leading_zero else 1
            for d in range(start_d, min(up, limit) + 1):
                new_tight = tight and (d == up)
                new_lz = leading_zero and (d == 0)
                ans += dfs(pos + 1, new_tight, new_lz)
            if not leading_zero:
                # can skip to suffix if remaining matches
                pass
            memo[key] = ans
            return ans
        memo = {}
        res += dfs(0, True, True)
        return res
    return count(finish) - count(start - 1)
