from typing import List
def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if rank[px] < rank[py]:
            parent[px] = py
        elif rank[px] > rank[py]:
            parent[py] = px
        else:
            parent[py] = px
            rank[px] += 1
    MAX = 10**5 + 10
    last = [-1] * MAX
    def get_primes(x):
        primes = set()
        if x % 2 == 0:
            primes.add(2)
            while x % 2 == 0:
                x //= 2
        i = 3
        while i * i <= x:
            if x % i == 0:
                primes.add(i)
                while x % i == 0:
                    x //= i
            i += 2
        if x > 1:
            primes.add(x)
        return primes
    for i in range(n):
        if nums[i] == 1:
            continue
        primes = get_primes(nums[i])
        for p in primes:
            if last[p] != -1:
                union(i, last[p])
            last[p] = i
    roots = set()
    for i in range(n):
        if nums[i] == 1:
            roots.add(i)
        else:
            roots.add(find(i))
    return len(roots) == 1
