def minCost(s1: str, s2: str, x: int) -> int:
    import sys
    pos = [i for i in range(len(s1)) if s1[i] != s2[i]]
    m = len(pos)
    if m % 2 == 1:
        return -1
    if m == 0:
        return 0
    dp = [[sys.maxsize] * m for _ in range(m)]
    for length in range(2, m + 1, 2):
        for i in range(m - length + 1):
            j = i + length - 1
            if length == 2:
                dp[i][j] = min(x, pos[j] - pos[i])
                continue
            for k in range(i + 1, j, 2):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])
            dp[i][j] = min(dp[i][j], dp[i + 1][j - 1] + min(x, pos[j] - pos[i]))
    return dp[0][m - 1]
