def maximumSumQueries(nums1, nums2, queries):
    n = len(nums1)
    points = sorted([(nums1[i], nums2[i]) for i in range(n)], reverse=True)
    q = sorted([(queries[i][0], queries[i][1], i) for i in range(len(queries))], reverse=True)
    ans = [-1] * len(queries)
    max_b = sorted(set(nums2))
    b_to_idx = {b: idx for idx, b in enumerate(max_b)}
    m = len(max_b)
    tree = [-1] * (4 * m)
    def update(idx, val, node=1, l=0, r=m-1):
        if l == r:
            tree[node] = max(tree[node], val)
            return
        mid = (l + r) // 2
        if idx <= mid:
            update(idx, val, node*2, l, mid)
        else:
            update(idx, val, node*2+1, mid+1, r)
        tree[node] = max(tree[node*2], tree[node*2+1])
    def query(idx, node=1, l=0, r=m-1):
        if idx > r:
            return -1
        if idx <= l:
            return tree[node]
        mid = (l + r) // 2
        return max(query(idx, node*2, l, mid), query(idx, node*2+1, mid+1, r))
    j = 0
    for x, y, qi in q:
        while j < n and points[j][0] >= x:
            a, b = points[j]
            idx = b_to_idx[b]
            update(idx, a + b)
            j += 1
        if y > max_b[-1]:
            ans[qi] = -1
            continue
        idx = bisect.bisect_left(max_b, y)
        ans[qi] = query(idx)
    return ans
